BEGIN TRANSACTION;
CREATE TABLE "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL);
CREATE TABLE "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" integer NOT NULL REFERENCES "account_emailaddress" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "django_site" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "domain" varchar(100) NOT NULL UNIQUE);
CREATE TABLE "socialaccount_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(200) NOT NULL, "uid" varchar(191) NOT NULL, "last_login" datetime NOT NULL, "date_joined" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "extra_data" text NOT NULL CHECK ((JSON_VALID("extra_data") OR "extra_data" IS NULL)));
CREATE TABLE "socialaccount_socialapp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "name" varchar(40) NOT NULL, "client_id" varchar(191) NOT NULL, "secret" varchar(191) NOT NULL, "key" varchar(191) NOT NULL, "provider_id" varchar(200) NOT NULL, "settings" text NOT NULL CHECK ((JSON_VALID("settings") OR "settings" IS NULL)));
CREATE TABLE "socialaccount_socialapp_sites" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "socialapp_id" integer NOT NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "socialaccount_socialtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "token_secret" text NOT NULL, "expires_at" datetime NULL, "account_id" integer NOT NULL REFERENCES "socialaccount_socialaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "app_id" integer NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_cajavehiculo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "country" varchar(2) NOT NULL);
CREATE TABLE "taller_cajavehiculo_modelos" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cajavehiculo_id" bigint NOT NULL REFERENCES "taller_cajavehiculo" ("id") DEFERRABLE INITIALLY DEFERRED, "modelo_id" bigint NOT NULL REFERENCES "taller_modelo" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_catalogomodeloauto" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "marca" varchar(100) NOT NULL, "modelo" varchar(150) NOT NULL, "fecha_creacion" datetime NOT NULL, "activo" bool NOT NULL);
CREATE TABLE "taller_categoriarepuesto" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "nombre" varchar(120) NOT NULL, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_categoriaservicio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "country" varchar(2) NOT NULL, "code" varchar(50) NULL, "activo" bool NOT NULL, "icono" varchar(50) NOT NULL, "orden" integer unsigned NOT NULL CHECK ("orden" >= 0));
CREATE TABLE "taller_categoriaservicioname" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(2) NOT NULL, "label" varchar(100) NOT NULL, "aliases" text NOT NULL CHECK ((JSON_VALID("aliases") OR "aliases" IS NULL)), "is_default" bool NOT NULL, "categoria_id" bigint NOT NULL REFERENCES "taller_categoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_ciudad" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "region_id" bigint NOT NULL REFERENCES "taller_region" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_ciudad_usa" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "poblacion" integer NULL, "es_capital" bool NOT NULL, "latitud" decimal NULL, "longitud" decimal NULL, "sales_tax_local" decimal NOT NULL, "estado_id" bigint NOT NULL REFERENCES "taller_estado" ("id") DEFERRABLE INITIALLY DEFERRED, "codigo_ibge" varchar(7) NULL, "nome" varchar(100) NULL);
CREATE TABLE "taller_cliente" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "nombre" varchar(100) NOT NULL, "apellido" varchar(100) NULL, "telefono" varchar(15) NULL, "direccion" varchar(255) NULL, "zipcode" varchar(10) NULL, "email" varchar(254) NULL, "ciudad_usa_id" bigint NULL REFERENCES "taller_ciudad_usa" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "updated_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "color_id" bigint NULL REFERENCES "taller_color_cliente" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "estado_usa_id" bigint NULL REFERENCES "taller_estado" ("id") DEFERRABLE INITIALLY DEFERRED, "ciudad_id" bigint NULL REFERENCES "taller_ciudad" ("id") DEFERRABLE INITIALLY DEFERRED, "region_id" bigint NULL REFERENCES "taller_region" ("id") DEFERRABLE INITIALLY DEFERRED, "billing_address_id" bigint NULL REFERENCES "ubicacion_address" ("id") DEFERRABLE INITIALLY DEFERRED, "shipping_address_id" bigint NULL REFERENCES "ubicacion_address" ("id") DEFERRABLE INITIALLY DEFERRED, "tax_id_type" varchar(12) NOT NULL, "tax_id" varchar(32) NOT NULL);
CREATE TABLE "taller_color_cliente" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(50) NOT NULL, "country" varchar(2) NULL, "codigo_color" varchar(7) NOT NULL, "activo" bool NOT NULL, "orden" integer unsigned NOT NULL CHECK ("orden" >= 0));
CREATE TABLE "taller_colorvehiculo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "hex" varchar(7) NULL, "country" varchar(2) NOT NULL, "nombre" varchar(50) NOT NULL);
CREATE TABLE "taller_companysettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "company_name" varchar(255) NOT NULL, "tagline" varchar(200) NOT NULL, "logo" varchar(100) NULL, "primary_color" varchar(7) NOT NULL, "secondary_color" varchar(7) NOT NULL, "address" text NOT NULL, "phone" varchar(50) NOT NULL, "email" varchar(254) NOT NULL, "website" varchar(200) NOT NULL, "tax_id" varchar(50) NOT NULL, "business_license" varchar(100) NOT NULL, "currency" varchar(3) NOT NULL, "timezone" varchar(50) NOT NULL, "invoice_prefix" varchar(10) NOT NULL, "quote_prefix" varchar(10) NOT NULL, "work_order_prefix" varchar(10) NOT NULL, "about_text" text NOT NULL, "terms_and_conditions" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "apply_tax_by_default" bool NOT NULL, "separate_by_technician" bool NOT NULL, "tax_rate" decimal NOT NULL);

