CREATE TABLE "taller_companysettingshistory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "changed_at" datetime NOT NULL, "field_changed" varchar(100) NOT NULL, "old_value" text NOT NULL, "new_value" text NOT NULL, "changed_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "company_settings_id" bigint NOT NULL REFERENCES "taller_companysettings" ("id") DEFERRABLE INITIALLY DEFERRED);

