CREATE TABLE "taller_comprobantepago" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha_subida" datetime NOT NULL, "metodo_pago" varchar(20) NOT NULL, "monto" decimal NOT NULL, "moneda" varchar(3) NOT NULL, "comprobante" varchar(100) NOT NULL, "numero_transaccion" varchar(100) NOT NULL, "estado" varchar(20) NOT NULL, "fecha_procesado" datetime NULL, "procesado_por" varchar(100) NOT NULL, "descripcion" text NOT NULL, "notas_admin" text NOT NULL, "plan_solicitado" varchar(20) NOT NULL, "meses_pagados" integer unsigned NOT NULL CHECK ("meses_pagados" >= 0), "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_configuracionempresa" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_publico" varchar(150) NOT NULL, "tagline" varchar(180) NOT NULL, "logo" varchar(100) NULL, "direccion" varchar(200) NOT NULL, "telefono" varchar(40) NOT NULL, "email_contacto" varchar(254) NOT NULL, "sitio_web" varchar(200) NOT NULL, "moneda" varchar(10) NOT NULL, "tasa_impuesto" decimal NOT NULL, "aplicar_impuesto_por_defecto" bool NOT NULL, "brand_color" varchar(7) NOT NULL, "dividir_por_tecnico" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "empresa_id" bigint NOT NULL UNIQUE REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "tecnico_por_defecto_id" bigint NULL REFERENCES "taller_tecnico" ("id") DEFERRABLE INITIALLY DEFERRED, "legal_address_id" bigint NULL REFERENCES "ubicacion_address" ("id") DEFERRABLE INITIALLY DEFERRED, "use_address_v2" bool NOT NULL, "rubro_principal" varchar(30) NOT NULL, "usa_kilometraje" bool NOT NULL, "usa_otros_servicios" bool NOT NULL, "usa_servicios" bool NOT NULL, "usa_vehiculos" bool NOT NULL);
CREATE TABLE "taller_detalledocumento" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(255) NOT NULL, "precio_venta" decimal NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "subtotal" decimal NOT NULL, "documento_id" bigint NOT NULL REFERENCES "taller_documento" ("id") DEFERRABLE INITIALLY DEFERRED, "tipo_item" varchar(20) NOT NULL);
CREATE TABLE "taller_documento" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "updated_at" datetime NOT NULL, "tipo" varchar(4) NOT NULL, "numero" varchar(32) NOT NULL, "estado" varchar(12) NOT NULL, "fecha_emision" date NOT NULL, "moneda" varchar(3) NOT NULL, "country" varchar(2) NOT NULL, "neto_repuestos" decimal NOT NULL, "neto_servicios" decimal NOT NULL, "neto_otros_servicios" decimal NOT NULL, "descuento" decimal NOT NULL, "tax_rate_applied" decimal NOT NULL, "tax_amount" decimal NOT NULL, "total" decimal NOT NULL, "created_at" datetime NOT NULL, "estado_pago" varchar(10) NOT NULL, "pagado" bool NOT NULL, "apply_vat" bool NOT NULL, "kilometraje" integer unsigned NULL CHECK ("kilometraje" >= 0), "millas" integer unsigned NULL CHECK ("millas" >= 0), "observaciones" text NULL, "cliente_id" bigint NOT NULL REFERENCES "taller_cliente" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "updated_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "tecnico_responsable_id" bigint NULL REFERENCES "taller_tecnico" ("id") DEFERRABLE INITIALLY DEFERRED, "vehiculo_id" bigint NULL REFERENCES "taller_vehiculo" ("id") DEFERRABLE INITIALLY DEFERRED, "fecha_pago" datetime NULL, "metodo_pago" varchar(20) NULL, "monto_pagado" decimal NOT NULL, "nota_pago" text NULL, "saldo_pendiente" decimal NOT NULL, "ult4" varchar(4) NULL, "payment_status" varchar(20) NOT NULL, "total_otros" decimal NOT NULL, "iva" decimal NOT NULL, "total_general" decimal NOT NULL, "total_repuestos" decimal NOT NULL, "total_servicios" decimal NOT NULL);
CREATE TABLE "taller_documentsequence" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tipo" varchar(3) NOT NULL, "current" integer unsigned NOT NULL CHECK ("current" >= 0), "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_empresa" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "empresa" varchar(100) NOT NULL, "pais" varchar(2) NOT NULL, "logo" varchar(100) NULL, "direccion" varchar(200) NOT NULL, "telefono" varchar(20) NOT NULL, "email" varchar(100) NOT NULL, "zona_horaria" varchar(50) NOT NULL, "fecha_inicio" datetime NOT NULL, "fecha_fin" datetime NULL, "plan" varchar(20) NOT NULL, "dias_prueba" integer unsigned NOT NULL CHECK ("dias_prueba" >= 0), "suscripcion_activa" bool NOT NULL, "ultimo_pago" datetime NULL, "valor_mensual" decimal NOT NULL, "moneda" varchar(3) NOT NULL, "notificacion_5_dias" bool NOT NULL, "notificacion_1_dia" bool NOT NULL, "notificacion_vencido" bool NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "nombre_taller" varchar(100) NOT NULL, CONSTRAINT "empresa_dias_prueba_gte_0" CHECK ("dias_prueba" >= 0), CONSTRAINT "empresa_valor_mensual_gte_0" CHECK ("valor_mensual" >= '0'));

