CREATE TABLE "taller_estado" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "codigo" varchar(10) NOT NULL, "sales_tax" decimal NOT NULL, "timezone" varchar(50) NOT NULL, "codigo_ibge" varchar(2) NULL, "nome" varchar(100) NULL, "sigla" varchar(5) NULL, "pais" varchar(2) NOT NULL);
CREATE TABLE "taller_lineaotroservicio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(255) NOT NULL, "empresa_externa" varchar(255) NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "costo_interno" decimal NOT NULL, "observaciones" text NULL, "documento_id" bigint NOT NULL REFERENCES "taller_documento" ("id") DEFERRABLE INITIALLY DEFERRED, "servicio_id" bigint NULL REFERENCES "taller_servicio" ("id") DEFERRABLE INITIALLY DEFERRED, "tecnico_responsable_id" bigint NULL REFERENCES "taller_tecnico" ("id") DEFERRABLE INITIALLY DEFERRED, "precio_cliente" decimal NOT NULL);
CREATE TABLE "taller_linearepuesto" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(100) NOT NULL, "nombre" varchar(255) NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "descuento" decimal NOT NULL, "observaciones" text NULL, "documento_id" bigint NOT NULL REFERENCES "taller_documento" ("id") DEFERRABLE INITIALLY DEFERRED, "repuesto_id" bigint NULL REFERENCES "taller_repuesto" ("id") DEFERRABLE INITIALLY DEFERRED, "tecnico_responsable_id" bigint NULL REFERENCES "taller_tecnico" ("id") DEFERRABLE INITIALLY DEFERRED, "precio_unitario" decimal NOT NULL, "part_id" bigint NULL REFERENCES "taller_part" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_lineaservicio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(255) NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "descuento" decimal NOT NULL, "observaciones" text NULL, "documento_id" bigint NOT NULL REFERENCES "taller_documento" ("id") DEFERRABLE INITIALLY DEFERRED, "servicio_id" bigint NULL REFERENCES "taller_servicio" ("id") DEFERRABLE INITIALLY DEFERRED, "tecnico_responsable_id" bigint NULL REFERENCES "taller_tecnico" ("id") DEFERRABLE INITIALLY DEFERRED, "precio_unitario" decimal NOT NULL, "service_id" bigint NULL REFERENCES "taller_service" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_marca" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(50) NOT NULL, "country" varchar(2) NOT NULL);
CREATE TABLE "taller_marcavehiculo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL UNIQUE, "nombre_en" varchar(100) NOT NULL, "pais_origen" varchar(50) NOT NULL, "activa" bool NOT NULL, "anio_inicio" integer unsigned NOT NULL CHECK ("anio_inicio" >= 0), "anio_fin" integer unsigned NULL CHECK ("anio_fin" >= 0));
CREATE TABLE "taller_modelo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(50) NOT NULL, "country" varchar(2) NOT NULL, "marca_id" bigint NOT NULL REFERENCES "taller_marca" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_modelovehiculo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "nombre_en" varchar(100) NOT NULL, "anio_inicio" integer unsigned NOT NULL CHECK ("anio_inicio" >= 0), "anio_fin" integer unsigned NULL CHECK ("anio_fin" >= 0), "tipo_vehiculo" varchar(50) NOT NULL, "activo" bool NOT NULL, "marca_id" bigint NOT NULL REFERENCES "taller_marcavehiculo" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_motorvehiculo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "country" varchar(2) NOT NULL);
CREATE TABLE "taller_motorvehiculo_modelos" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "motorvehiculo_id" bigint NOT NULL REFERENCES "taller_motorvehiculo" ("id") DEFERRABLE INITIALLY DEFERRED, "modelo_id" bigint NOT NULL REFERENCES "taller_modelo" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_pagopendiente" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "plan" varchar(20) NOT NULL, "monto" decimal NOT NULL, "comprobante" varchar(100) NOT NULL, "estado" varchar(20) NOT NULL, "fecha_subida" datetime NOT NULL, "fecha_verificacion" datetime NULL, "notas" text NOT NULL, "referencia" varchar(100) NOT NULL, "metodo_pago" varchar(50) NOT NULL, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "verificado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_part" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category" varchar(64) NOT NULL, "brand" varchar(64) NOT NULL, "unit" varchar(16) NOT NULL, "weight_kg" decimal NULL, "purchase_price" decimal NULL, "stock_quantity" decimal NOT NULL, "stock_min" decimal NOT NULL, "active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "empresa_id" bigint NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "sku" varchar(64) NOT NULL UNIQUE);
CREATE TABLE "taller_parti18n" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "locale" varchar(8) NOT NULL, "display_name" varchar(160) NOT NULL, "synonyms" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "part_id" bigint NOT NULL REFERENCES "taller_part" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_partprice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "currency" varchar(3) NOT NULL, "price" decimal NOT NULL, "valid_from" date NOT NULL, "valid_to" date NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "company_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "part_id" bigint NOT NULL REFERENCES "taller_part" ("id") DEFERRABLE INITIALLY DEFERRED, "tax_policy_id" bigint NULL REFERENCES "taller_taxpolicy" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_perfilusuario" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "pais" varchar(2) NOT NULL, "region" varchar(100) NULL, "state" varchar(100) NULL, "zipcode" varchar(20) NULL, "fecha_creacion" datetime NOT NULL, "ciudad_id" bigint NULL REFERENCES "taller_ciudad_usa" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_preciosuscripcion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tipo_plan" varchar(20) NOT NULL, "pais" varchar(2) NOT NULL, "precio" decimal NOT NULL, "moneda" varchar(3) NOT NULL, "activo" bool NOT NULL, "nombre_plan" varchar(100) NOT NULL, "descripcion" text NOT NULL, "documentos_ilimitados" bool NOT NULL, "soporte_prioritario" bool NOT NULL, "reportes_avanzados" bool NOT NULL, "diagnostico_ia" bool NOT NULL, "api_incluida" bool NOT NULL, "multisucursal" bool NOT NULL, "usuarios_incluidos" integer unsigned NOT NULL CHECK ("usuarios_incluidos" >= 0));
CREATE TABLE "taller_region" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL);
CREATE TABLE "taller_repuesto" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "part_number" varchar(64) NULL, "nombre" varchar(160) NOT NULL, "precio_compra" decimal NOT NULL, "precio_venta" decimal NOT NULL, "cantidad_stock" integer unsigned NOT NULL CHECK ("cantidad_stock" >= 0), "proveedor" varchar(200) NULL, "categoria_id" bigint NULL REFERENCES "taller_categoriarepuesto" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_service" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category" varchar(64) NOT NULL, "std_hours" decimal NULL, "active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "empresa_id" bigint NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "code" varchar(64) NOT NULL UNIQUE);
CREATE TABLE "taller_servicei18n" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "locale" varchar(8) NOT NULL, "display_name" varchar(160) NOT NULL, "synonyms" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "service_id" bigint NOT NULL REFERENCES "taller_service" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_serviceprice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "currency" varchar(3) NOT NULL, "price" decimal NOT NULL, "valid_from" date NOT NULL, "valid_to" date NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "company_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "service_id" bigint NOT NULL REFERENCES "taller_service" ("id") DEFERRABLE INITIALLY DEFERRED, "tax_policy_id" bigint NULL REFERENCES "taller_taxpolicy" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_servicio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "nombre" varchar(160) NOT NULL, "categoria_id" bigint NOT NULL REFERENCES "taller_categoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "subcategoria_id" bigint NULL REFERENCES "taller_subcategoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED, "activo" bool NOT NULL, "codigo_interno" varchar(50) NOT NULL, "descripcion" text NOT NULL, "duracion_estimada_min" integer unsigned NULL CHECK ("duracion_estimada_min" >= 0), "precio_base" decimal NULL, "rubro_efectivo" varchar(30) NULL, "rubro_sugerido" varchar(30) NULL, "servicio_base_id" bigint NULL REFERENCES "taller_serviciobase" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_servicio_empresa_nombre_categoria" UNIQUE ("empresa_id", "nombre", "categoria_id"));
CREATE TABLE "taller_serviciobase" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(255) NOT NULL, "descripcion" text NOT NULL, "duracion_estimada_min" integer unsigned NULL CHECK ("duracion_estimada_min" >= 0), "codigo_interno" varchar(50) NOT NULL, "rubro_sugerido" varchar(30) NULL, "es_generico" bool NOT NULL, "activo" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "subcategoria_id" bigint NOT NULL REFERENCES "taller_subcategoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_servicioexterno" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "nombre" varchar(160) NOT NULL, "empresa_externa" varchar(255) NOT NULL, "costo_taller" decimal NOT NULL, "precio_cliente" decimal NOT NULL, "descripcion" text NULL, "tiempo_estimado" varchar(100) NULL, "activo" bool NOT NULL, "categoria_id" bigint NOT NULL REFERENCES "taller_categoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "subcategoria_id" bigint NULL REFERENCES "taller_subcategoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_servicio_externo_empresa_nombre_proveedor" UNIQUE ("empresa_id", "nombre", "empresa_externa"));
CREATE TABLE "taller_servicioname" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(2) NOT NULL, "label" varchar(100) NOT NULL, "aliases" text NOT NULL CHECK ((JSON_VALID("aliases") OR "aliases" IS NULL)), "is_default" bool NOT NULL, "servicio_id" bigint NOT NULL REFERENCES "taller_servicio" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_subcategoriaservicio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "country" varchar(2) NOT NULL, "code" varchar(50) NULL, "categoria_id" bigint NOT NULL REFERENCES "taller_categoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED, "activo" bool NOT NULL, "orden" integer unsigned NOT NULL CHECK ("orden" >= 0));
CREATE TABLE "taller_subcategoriaservicioname" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(2) NOT NULL, "label" varchar(100) NOT NULL, "aliases" text NOT NULL CHECK ((JSON_VALID("aliases") OR "aliases" IS NULL)), "is_default" bool NOT NULL, "subcategoria_id" bigint NOT NULL REFERENCES "taller_subcategoriaservicio" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_suscripcion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tipo" varchar(20) NOT NULL, "fecha_inicio" date NULL, "fecha_fin" date NULL, "activa" bool NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_tallerinfo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_taller" varchar(255) NOT NULL, "telefono" varchar(32) NOT NULL, "ha_usado_prueba" bool NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_taxpolicy" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "country" varchar(2) NOT NULL, "state_code" varchar(10) NOT NULL, "city_name" varchar(80) NOT NULL, "applies_to" varchar(10) NOT NULL, "rate" decimal NOT NULL, "inclusive" bool NOT NULL, "active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "taller_team_member" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rol" varchar(50) NOT NULL, "is_active" bool NOT NULL, "fecha_creacion" datetime NOT NULL, "fecha_actualizacion" datetime NOT NULL, "notas" text NULL, "creado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_tecnico" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "telefono" varchar(20) NULL, "direccion" text NULL, "fecha_creacion" datetime NOT NULL, "fecha_modificacion" datetime NOT NULL, "empresa_id" bigint NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "rol" varchar(12) NOT NULL, "activo" bool NOT NULL);
CREATE TABLE "taller_tienda" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "direccion" varchar(255) NULL, "telefono" varchar(20) NULL, "email" varchar(254) NULL, "sitio_web" varchar(200) NULL, "ciudad" varchar(100) NULL, "region" varchar(100) NULL, "activo" bool NOT NULL, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "taller_trialregistro" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "telefono" varchar(20) NOT NULL UNIQUE, "codigo" varchar(32) NOT NULL UNIQUE, "fecha_registro" datetime NOT NULL, "fecha_activacion" datetime NULL, "prueba_activa" bool NOT NULL, "prueba_expirada" bool NOT NULL, "ip" char(39) NULL, "user_agent" text NULL);
CREATE TABLE "taller_vehiculo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "marca_texto" varchar(100) NULL, "modelo_texto" varchar(150) NULL, "patente" varchar(20) NOT NULL, "anio" integer unsigned NOT NULL CHECK ("anio" >= 0), "vin" varchar(50) NULL, "millas" integer unsigned NULL CHECK ("millas" >= 0), "caja_id" bigint NULL REFERENCES "taller_cajavehiculo" ("id") DEFERRABLE INITIALLY DEFERRED, "cliente_id" bigint NOT NULL REFERENCES "taller_cliente" ("id") DEFERRABLE INITIALLY DEFERRED, "color_id" bigint NULL REFERENCES "taller_colorvehiculo" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED, "marca_id" bigint NULL REFERENCES "taller_marca" ("id") DEFERRABLE INITIALLY DEFERRED, "modelo_id" bigint NULL REFERENCES "taller_modelo" ("id") DEFERRABLE INITIALLY DEFERRED, "motor_id" bigint NULL REFERENCES "taller_motorvehiculo" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_empresa_patente" UNIQUE ("empresa_id", "patente"));
CREATE TABLE "taller_venta" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha" date NOT NULL, "total" decimal NOT NULL, "cliente_id" bigint NOT NULL REFERENCES "taller_cliente" ("id") DEFERRABLE INITIALLY DEFERRED, "documento_relacionado_id" bigint NULL REFERENCES "taller_documento" ("id") DEFERRABLE INITIALLY DEFERRED, "empresa_id" bigint NOT NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ubicacion_address" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "line1" varchar(160) NOT NULL, "line2" varchar(160) NOT NULL, "postal_code" varchar(20) NOT NULL, "latitude" decimal NULL, "longitude" decimal NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "city_id" bigint NOT NULL REFERENCES "taller_ciudad_usa" ("id") DEFERRABLE INITIALLY DEFERRED, "company_id" bigint NULL REFERENCES "taller_empresa" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ubicacion_ciudad" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "zip_code" varchar(10) NOT NULL UNIQUE, "estado_id" bigint NOT NULL REFERENCES "ubicacion_estado" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ubicacion_estado" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL);
